// VoiceGuard 답을 채팅 답으로 바꾼다. n8n 채팅 창은 마지막 노드의 output 필드를 보여준다.
const r = $input.first().json;
const base = String($('설정').first().json.base_url || '').replace(/\/+$/, '');
let output;
if (typeof r.answer === 'string' && r.answer.trim()) {
  // 채팅 창은 답을 마크다운으로 그려 이미지 주소를 저절로 불러오므로, 이미지는 대체 글만 남긴다(서버도 지운다).
  output = r.answer.trim().replace(/!\[([^\]\n]*)\]\([^)\n]*\)/g, '$1').replace(/!\[/g, '!\\[');
  // 답에 나온 상대 주소(/calls/…, /dashboard…)를 서버 주소로 바꾼다.
  output = output.replace(/(^|[\s(<\[])(\/(?:calls|dashboard)\b[^\s)>\]]*)/g, (m, pre, path) => pre + base + path);
  const cases = Array.isArray(r.cases) ? r.cases.slice(0, 5) : [];
  if (cases.length) {
    output += '\n\n대시보드에서 보기: ' + cases.map((id) => `[통화 #${id}](${base}/dashboard#case=${id})`).join(' · ');
  }
} else if (r.error) {
  // 서버에 닿지 못함(시간 초과, 연결 실패)
  const reason = typeof r.error === 'string' ? r.error : (r.error.message || '');
  output = 'VoiceGuard 서버에 연결하지 못했습니다. 잠시 뒤 다시 물어봐 주세요.' + (reason ? ` (${reason})` : '');
} else {
  // 서버가 받지 않음(관리 코드가 틀리면 401, 너무 많이 틀리면 429, Claude 키가 없으면 503)
  const detail = typeof r.detail === 'string' ? r.detail : '';
  output = 'VoiceGuard 서버가 요청을 처리하지 못했습니다.' + (detail ? ' ' + detail : '');
  if (detail.includes('코드')) output += " 'VoiceGuard에 질문' 노드의 자격 증명(X-Admin-Code)을 확인해 주세요.";
}
return [{ json: { output } }];
